sql.where:
c.teacher_id = (SELECT t.teacher_id FROM teachers t JOIN users u ON u.user_id = t.user_id WHERE u.login_id = #{loginId})
AND c.status_code = #{cond.statusCode}
AND (c.class_name ILIKE '%' || #{cond.keyword} || '%' OR c.subject ILIKE '%' || #{cond.keyword} || '%')

mapper.select:
SELECT COUNT(*)
  FROM classes c
  JOIN teachers t ON c.teacher_id = t.teacher_id
  JOIN users    u ON t.user_id    = u.user_id
 WHERE u.login_id = #{loginId}
   AND c.class_id = #{classId}
